"""Profil the parquet cache generated by :mod:`src.command.loader`."""

from __future__ import annotations

import argparse
from dataclasses import dataclass
from datetime import date, datetime
import json
from pathlib import Path
import re
from typing import Any

import polars as pl

from src.profiling.column_profiler import ColumnProfiler


EMAIL_RE = re.compile(r"^[^\s@]+@[^\s@]+\.[^\s@]+$")
PHONE_RE = re.compile(r"^[+()\d][\d .()/-]{5,}$")
INTEGER_RE = re.compile(r"^[+-]?\d+$")
NUMBER_RE = re.compile(r"^[+-]?(?:\d+(?:[.,]\d+)?|[.,]\d+)$")
DATE_FORMATS = (
    "%Y-%m-%d",
    "%Y/%m/%d",
    "%d/%m/%Y",
    "%d-%m-%Y",
    "%d.%m.%Y",
)


def _json_value(value: Any) -> Any:
    """Convert Polars/Python scalar values into JSON-safe values."""

    if isinstance(value, (datetime, date)):
        return value.isoformat()
    if value is None or isinstance(value, (str, int, float, bool)):
        return value
    return str(value)


def _semantic_type(name: str, declared_type: str, values: list[Any]) -> str:
    """Infer a useful semantic type for mostly-string imported columns."""

    non_empty = [str(value).strip() for value in values if value is not None and str(value).strip()]
    if not non_empty:
        return "empty"

    lowered_name = name.casefold()
    lowered_values = {value.casefold() for value in non_empty}
    if lowered_values <= {"true", "false", "yes", "no", "oui", "non", "0", "1"}:
        return "boolean"
    if all(EMAIL_RE.fullmatch(value) for value in non_empty):
        return "email"
    if any(token in lowered_name for token in ("date", "naissance", "birth")):
        if all(_parse_date(value) is not None for value in non_empty):
            return "date"
    if all(_parse_date(value) is not None for value in non_empty):
        return "date"
    if all(PHONE_RE.fullmatch(value) for value in non_empty) and any(
        character.isdigit() for character in non_empty[0]
    ):
        return "phone"
    if all(INTEGER_RE.fullmatch(value) for value in non_empty):
        if any(token in lowered_name for token in ("code", "postal", "iban", "bic", "id")):
            return "identifier"
        return "integer"
    if all(NUMBER_RE.fullmatch(value) for value in non_empty):
        return "number"
    if declared_type.lower() not in {"string", "str"}:
        return declared_type
    return "text"


def _parse_date(value: str) -> date | None:
    for date_format in DATE_FORMATS:
        try:
            return datetime.strptime(value, date_format).date()
        except ValueError:
            continue
    return None


@dataclass
class ProfilingEngine:
    """Compute structural and quality statistics from a parquet cache."""

    cache: Path | str = Path("cache/profile.parquet")
    sample_size: int = 10_000
    top_values: int = 5

    def __post_init__(self) -> None:
        self.cache = Path(self.cache)
        if not self.cache.exists():
            raise FileNotFoundError(f"Cache parquet introuvable : {self.cache}")
        if not self.cache.is_file():
            raise ValueError(f"Le cache ne désigne pas un fichier : {self.cache}")
        if self.sample_size <= 0:
            raise ValueError("sample_size doit être strictement positif")
        if self.top_values < 0:
            raise ValueError("top_values ne peut pas être négatif")

    def profile(self) -> dict[str, Any]:
        """Return a JSON-serializable profiling report."""

        # Keep the historical command API while delegating to the canonical
        # profiler implementation used by the semantic pipeline.
        return ColumnProfiler(self.cache, self.sample_size, self.top_values).profile()

        query = pl.scan_parquet(self.cache)
        schema = query.collect_schema()
        columns = list(schema.names())
        if not columns:
            return {
                "cache": str(self.cache),
                "rows": 0,
                "columns": 0,
                "duplicate_rows": 0,
                "duplicate_rate": 0.0,
                "column_profiles": [],
            }

        row_count = int(query.select(pl.len()).collect().item())
        sample = query.head(self.sample_size).collect()
        aggregate = self._aggregate_columns(query, columns, schema)
        duplicate_rows = self._duplicate_rows(query, columns)

        column_profiles: list[dict[str, Any]] = []
        for index, name in enumerate(columns):
            declared_type = str(schema[name])
            prefix = f"c{index}_"
            values = sample.get_column(name).to_list()
            stats = aggregate
            null_count = int(stats[f"{prefix}null_count"] or 0)
            empty_count = int(stats[f"{prefix}empty_count"] or 0)
            non_null_count = int(stats[f"{prefix}non_null_count"] or 0)
            distinct_count = int(stats[f"{prefix}distinct_count"] or 0)
            duplicate_values = max(non_null_count - distinct_count, 0)

            column_profiles.append(
                {
                    "name": name,
                    "declared_type": declared_type,
                    "semantic_type": _semantic_type(name, declared_type, values),
                    "null_count": null_count,
                    "null_rate": self._rate(null_count, row_count),
                    "empty_count": empty_count,
                    "empty_rate": self._rate(empty_count, row_count),
                    "non_null_count": non_null_count,
                    "distinct_count": distinct_count,
                    "duplicate_values": duplicate_values,
                    "min": _json_value(stats[f"{prefix}min"]),
                    "max": _json_value(stats[f"{prefix}max"]),
                    "top_values": self._top_values(query, name),
                }
            )

        return {
            "cache": str(self.cache),
            "rows": row_count,
            "columns": len(columns),
            "duplicate_rows": duplicate_rows,
            "duplicate_rate": self._rate(duplicate_rows, row_count),
            "column_profiles": column_profiles,
        }

    def _aggregate_columns(
        self,
        query: pl.LazyFrame,
        columns: list[str],
        schema: pl.Schema,
    ) -> dict[str, Any]:
        expressions: list[pl.Expr] = []
        for index, name in enumerate(columns):
            prefix = f"c{index}_"
            column = pl.col(name)
            is_string = schema[name] == pl.String
            empty = (
                column.str.strip_chars().eq("").fill_null(False).sum()
                if is_string
                else pl.lit(0)
            )
            expressions.extend(
                [
                    column.is_null().sum().alias(f"{prefix}null_count"),
                    column.is_not_null().sum().alias(f"{prefix}non_null_count"),
                    column.drop_nulls().n_unique().alias(f"{prefix}distinct_count"),
                    empty.alias(f"{prefix}empty_count"),
                    column.min().alias(f"{prefix}min"),
                    column.max().alias(f"{prefix}max"),
                ]
            )
        return query.select(expressions).collect().row(0, named=True)

    @staticmethod
    def _duplicate_rows(query: pl.LazyFrame, columns: list[str]) -> int:
        return int(
            query.select(pl.struct(columns).is_duplicated().sum().alias("duplicate_rows"))
            .collect()
            .item()
            or 0
        )

    def _top_values(self, query: pl.LazyFrame, name: str) -> list[dict[str, Any]]:
        if self.top_values == 0:
            return []
        counts = (
            query.select(pl.col(name).alias("value"))
            .drop_nulls()
            .group_by("value")
            .agg(pl.len().alias("count"))
            .sort("count", descending=True)
            .head(self.top_values)
            .collect()
        )
        return [
            {"value": _json_value(row["value"]), "count": int(row["count"])}
            for row in counts.to_dicts()
        ]

    @staticmethod
    def _rate(count: int, total: int) -> float:
        return round(count / total, 6) if total else 0.0

    def save_json(self, output: Path | str, report: dict[str, Any] | None = None) -> Path:
        """Write a profiling report to JSON and return its path."""

        destination = Path(output)
        destination.parent.mkdir(parents=True, exist_ok=True)
        report = report if report is not None else self.profile()
        destination.write_text(
            json.dumps(report, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
        return destination


def print_report(report: dict[str, Any]) -> None:
    """Print a compact human-readable report."""

    duplicates = report.get("exact_duplicates", {})
    duplicate_rows = duplicates.get("duplicate_rows", report.get("duplicate_rows", 0))
    duplicate_rate = duplicates.get("duplicate_rate", report.get("duplicate_rate", 0.0))
    print(f"Cache : {report['cache']}")
    print(f"Lignes : {report['rows']:,}")
    print(f"Colonnes : {report['columns']}")
    print(
        f"Doublons de lignes : {duplicate_rows:,} "
        f"({duplicate_rate:.2%})"
    )
    print("\nProfil des colonnes :")
    for column in report["column_profiles"]:
        print(
            f"- {column['name']}: {column.get('physical_type', column.get('declared_type'))} -> {column['semantic_type']} | "
            f"null_effectif={column.get('effective_null_rate', column['null_rate']):.2%}, "
            f"vide={column['empty_rate']:.2%}, distinctes={column['cardinality'] if 'cardinality' in column else column['distinct_count']:,}, "
            f"doublons={column['duplicate_values']:,}"
        )


def main() -> None:
    parser = argparse.ArgumentParser(description="Profile le cache parquet OSIRIS")
    parser.add_argument(
        "--cache",
        type=Path,
        default=Path("cache/profile.parquet"),
        help="Chemin du cache parquet",
    )
    parser.add_argument(
        "--json-out",
        type=Path,
        help="Écrit également le rapport dans ce fichier JSON",
    )
    parser.add_argument(
        "--sample-size",
        type=int,
        default=10_000,
        help="Nombre de valeurs échantillonnées pour le type sémantique",
    )
    args = parser.parse_args()

    engine = ProfilingEngine(cache=args.cache, sample_size=args.sample_size)
    report = engine.profile()
    print_report(report)
    if args.json_out:
        print(f"\nRapport JSON : {engine.save_json(args.json_out, report)}")


if __name__ == "__main__":
    main()
